content.text:
The root cause is a network delay on the `search` → `rate` connection, and the user-visible `/hotels` slowdown comes from it. Here is the analysis.

```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT round(avg(epoch_ms(s.time)-epoch_ms(c.time)),1) AS avg_start_gap_ms, round(min(epoch_ms(s.time)-epoch_ms(c.time)),1) AS min_gap, round(max(epoch_ms(s.time)-epoch_ms(c.time)),1) AS max_gap, round(avg(c.duration/1e6 - s.duration/1e6),1) AS avg_client_minus_server_ms, count(*) AS n FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.attr_span_kind='Server' WHERE c.service_name='search' AND c.span_name='rate.Rate/GetRates'",
          "claim": "search→rate GetRates calls wait ~1737ms before the rate server starts; server-side handling takes about 0.5ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT p, service_name, span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM (SELECT 'abn' p,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE service_name='search' AND span_name IN ('rate.Rate/GetRates','geo.Geo/Nearby') AND attr_span_kind='Client' GROUP BY ALL ORDER BY 3,1",
          "claim": "Only search's rate.Rate/GetRates client calls slowed (~1686ms vs 0.69ms normal); its geo calls stayed ~0.5ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT p, service_name, span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,2) avg_ms FROM (SELECT 'abn' p,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE service_name='rate' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "rate's own server span stays fast (~0.55ms abnormal vs ~0.42ms normal); the delay is not inside rate.",
          "note": ""
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, service_name, span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM (SELECT 'abn' p,* FROM abnormal_traces UNION ALL SELECT 'norm',* FROM normal_traces) WHERE (service_name='frontend' AND span_name IN ('HTTP /hotels','search.Search/Nearby')) OR (service_name='search' AND span_name='search.Search/Nearby' AND attr_span_kind='Server') GROUP BY ALL ORDER BY 2,3,1",
          "claim": "search.Search/Nearby server takes ~1687ms and frontend HTTP /hotels rises from ~3.8ms to ~1649ms."
        }
      ]
    }
  ]
}
```
